    while i < n {
        dist = dist.push(-1)
        done = done.push(false)
        i = i + 1
    }
    dist = set_int(dist, src, 0)

    var rounds = 0
    while rounds < n {
        var u = -1
        var best = 0
        var j = 0
        while j < n {
            let dj = at_int(dist, j)
            if dj >= 0 and not at_bool(done, j) {
                if u < 0 or dj < best {
                    u = j
                    best = dj
                }
            }
            j = j + 1
        }
        if u < 0 {
            break
        }
        done = set_bool(done, u, true)
        for e in edges {
